import { Group, PlaneGeometry, MeshBasicNodeMaterial, Vector2, DoubleSide } from 'three/webgpu';
import { texture as tslTexture } from 'three/tsl';
import { TimelineMax } from 'gsap';

/**
 * Creates a collection title node: a textured plane background with headline text overlay.
 *
 * @param {import('@/types').NodeConfig} config
 * @param {import('@/types').NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const {
    scenePosition = { x: 0, y: 3, z: 0 },
    sceneRotation = { x: 0, y: 0, z: 0 },
    sceneScale = { x: 1, y: 1, z: 1 },
    assets = {},
    textContent = [],
    visual = {},
    atlasRegion
  } = config;

  // --- Group that holds all elements ---
  const group = new Group();
  group.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  group.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);
  group.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  // --- Background plane with texture ---
  const imageUrl = assets.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const texture = ctx.textureLoader.load(imageUrl);

  // Apply atlas region if provided (assumes full image rect, no offset/repeat adjustment)
  if (atlasRegion) {
    const { sourceRect = { x: 0, y: 0, width: 512, height: 320 } } = atlasRegion;
    // If the image is exactly the source rect, no transform needed.
    // For a real atlas, we would compute repeat and offset here.
  }

  const planeWidth = 2.0;
  const planeHeight = planeWidth * (320 / 512); // maintain aspect ratio
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: DoubleSide,
    transparent: true,
    depthWrite: false // allows text to be drawn over it without z-fighting
  });
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // --- Headline text ---
  // Find the first text content with role "headline" (fallback to first entry)
  const headlineConfig = textContent.find(t => t.role === 'headline') || textContent[0];
  const headlineText = headlineConfig?.content || 'Collection';
  const headlineFontSize = headlineConfig?.size || 96; // pixel size hint
  const headlineWeight = headlineConfig?.weight || 400;

  // Use typography tokens: headline scene-unit height = 0.34
  const headlineHeight = 0.34; // scene units

  const textMesh = ctx.fontAtlas.createText({
    text: headlineText,
    fontFamily: 'Lora',
    fontWeight: headlineWeight,
    fontSize: headlineFontSize, // pixels for atlas resolution
    color: visual.colors?.paper || '#e8ecf2',
    anchorX: 'center',
    anchorY: 'middle'
  });
  // Scale text to match desired scene-unit height
  // The atlas returns a mesh whose pixel height is stored; we scale to headlineHeight
  const originalHeight = textMesh.geometry?.boundingBox?.max.y - textMesh.geometry?.boundingBox?.min.y || 1;
  const scaleFactor = headlineHeight / originalHeight;
  textMesh.scale.setScalar(scaleFactor);
  textMesh.position.set(0, 0, 0.001); // slight z offset to avoid z-fighting
  group.add(textMesh);

  // --- Event handlers (none defined) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill any GSAP timelines attached to the group
    if (group.userData.timeline) {
      group.userData.timeline.kill();
    }
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // Dispose text mesh resources
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    // Remove children from parent (should be done externally by scene manager)
  };

  return group;
}
